package com.leotv.detail;
final class PreloadHost {static Object call(Object o,String n,Object...args)throws ReflectiveOperationException{for(java.lang.reflect.Method m:o.getClass().getMethods())if(m.getName().equals(n)&&m.getParameterTypes().length==args.length){try{return m.invoke(o,args);}catch(IllegalArgumentException mismatch){}}throw new NoSuchMethodException(n);}static String text(Object o){return o==null?"":String.valueOf(o);}static Object field(Object o,String n)throws ReflectiveOperationException{return o.getClass().getField(n).get(o);}static void set(Object o,String n,Object v)throws ReflectiveOperationException{o.getClass().getField(n).set(o,v);}}
